using Mentorly.Application.DTOs;

namespace Mentorly.Application.Services;

public interface IUnitService { Task<IReadOnlyList<UnitDto>> GetByCourseAsync(Guid courseId, CancellationToken cancellationToken = default); Task<UnitDto?> CreateAsync(Guid courseId, CreateUnitDto dto, CancellationToken cancellationToken = default); Task<bool> UpdateAsync(Guid courseId, Guid unitId, UpdateUnitDto dto, CancellationToken cancellationToken = default); Task<bool> DeleteAsync(Guid courseId, Guid unitId, CancellationToken cancellationToken = default); Task<bool> ReorderAsync(Guid courseId, ReorderItemsDto dto, CancellationToken cancellationToken = default); }
public interface IThemeService { Task<IReadOnlyList<ThemeDto>> GetByUnitAsync(Guid unitId, CancellationToken cancellationToken = default); Task<ThemeDto?> CreateAsync(Guid unitId, CreateThemeDto dto, CancellationToken cancellationToken = default); Task<bool> UpdateAsync(Guid themeId, UpdateThemeDto dto, CancellationToken cancellationToken = default); Task<bool> DeleteAsync(Guid themeId, CancellationToken cancellationToken = default); Task<bool> ReorderAsync(Guid unitId, ReorderItemsDto dto, CancellationToken cancellationToken = default); }
public interface IActivityService { Task<IReadOnlyList<ActivityDto>> GetByThemeAsync(Guid themeId, CancellationToken cancellationToken = default); Task<ActivityDto?> GetByIdAsync(Guid activityId, CancellationToken cancellationToken = default); Task<ActivityDto?> CreateAsync(Guid themeId, CreateActivityDto dto, CancellationToken cancellationToken = default); Task<bool> UpdateAsync(Guid activityId, UpdateActivityDto dto, CancellationToken cancellationToken = default); Task<bool> DeleteAsync(Guid activityId, CancellationToken cancellationToken = default); Task<bool> ReorderAsync(Guid themeId, ReorderItemsDto dto, CancellationToken cancellationToken = default); }
